package com.hmdp.ai.application.dto.mcp;import com.hmdp.ai.domain.mcp.McpTransport;import javax.validation.constraints.*;import java.util.*;public class CreateMcpServerRequest {@NotBlank @Pattern(regexp="[A-Za-z0-9_-]{2,64}")private String code;@NotBlank @Size(max=128)private String name;@NotBlank @Size(max=128)private String namespace;@NotNull private McpTransport transport;@NotBlank @Size(max=1000)private String endpoint;@Size(max=255)private String secretRef;@Size(max=200)private List<@Size(max=255)String>allowedTools=new ArrayList<>();@Min(100)@Max(120000)private int timeoutMs=10000;private boolean allowPrivateNetwork;private boolean enabled=true;public String getCode(){return code;}public void setCode(String v){code=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getNamespace(){return namespace;}public void setNamespace(String v){namespace=v;}public McpTransport getTransport(){return transport;}public void setTransport(McpTransport v){transport=v;}public String getEndpoint(){return endpoint;}public void setEndpoint(String v){endpoint=v;}public String getSecretRef(){return secretRef;}public void setSecretRef(String v){secretRef=v;}public List<String>getAllowedTools(){return allowedTools;}public void setAllowedTools(List<String>v){allowedTools=v;}public int getTimeoutMs(){return timeoutMs;}public void setTimeoutMs(int v){timeoutMs=v;}public boolean isAllowPrivateNetwork(){return allowPrivateNetwork;}public void setAllowPrivateNetwork(boolean v){allowPrivateNetwork=v;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}}
